import json
from datetime import timezone
from pathlib import Path

from mock_api import TRACE, search
from query_audit import build_rejection
from window_projection import parse_bound, utc_pair


def _error(param, message, payload, normalized=None):
    """Build an audit error while retaining the values used for comparison."""
    error = build_rejection(param, message, payload)
    if normalized:
        error["normalized"] = dict(normalized)
    return error


def _utc_text(value):
    return value.isoformat()


def _parse_field(payload, param, normalized):
    if param not in payload:
        return None, None
    try:
        value = parse_bound(payload[param])
    except (TypeError, ValueError):
        return _error(
            param,
            "must be a valid ISO 8601 datetime",
            payload,
            normalized,
        ), None
    return None, value


def validate_range(payload):
    if not isinstance(payload, dict):
        return [_error("query", "must be an object", payload)]

    errors = []
    normalized = {}
    start_error, start = _parse_field(payload, "start_date", normalized)
    if start_error:
        errors.append(start_error)
    elif start is None:
        errors.append(_error("start_date", "is required", payload, normalized))
    else:
        normalized["start_date"] = _utc_text(start.astimezone(timezone.utc))

    end_error, end = _parse_field(payload, "end_date", normalized)
    if end_error:
        errors.append(end_error)
    elif end is not None:
        normalized["end_date"] = _utc_text(end.astimezone(timezone.utc))

    # An end is optional; without one there is no cross-field range to check.
    if start is None or end is None:
        return errors

    window = {"start": start, "end": end}
    start_utc, end_utc = utc_pair(window)
    comparison = {
        "start_utc": _utc_text(start_utc),
        "end_utc": _utc_text(end_utc),
    }
    if end_utc < start_utc:
        errors.append(
            _error(
                "date_range",
                "end must be on or after start after UTC normalization",
                payload,
                {**normalized, **comparison},
            )
        )

    # Fixed-offset ISO values do not carry a zone name, so the contract's
    # repeated-hour rule is represented by differing offsets on the same
    # local date and hour.  Apply it in addition to the UTC ordering check.
    start_local = start.replace(tzinfo=None)
    end_local = end.replace(tzinfo=None)
    if (
        start_local.date() == end_local.date()
        and start_local.hour == end_local.hour
        and start.utcoffset() != end.utcoffset()
        and end_local < start_local
    ):
        errors.append(
            _error(
                "date_range",
                "ambiguous fall-back DST range: end wall-clock time is earlier than start",
                payload,
                {**normalized, **comparison},
            )
        )
    return errors


def process_queries(path):
    TRACE.clear()
    payload = json.loads(Path(path).read_text(encoding="utf-8"))
    accepted = []
    rejected = []
    for index, query in enumerate(payload):
        errors = validate_range(query)
        if errors:
            rejected.append({"index": index, "errors": errors, "original": query})
            continue
        accepted.append(search(query))
    return {"accepted": accepted, "rejected": rejected, "trace": list(TRACE)}

